const statsByDept = `-- name: StatsByDept :many
SELECT organizer_dept_id::text AS key, count(*)::int AS count
FROM v_activity WHERE deleted = 0 AND tenant_id = $1 AND organizer_dept_id IS NOT NULL
GROUP BY organizer_dept_id ORDER BY count DESC
`

type StatsByDeptRow struct {
	Key   string `json:"key"`
	Count int32  `json:"count"`
}

func (q *Queries) StatsByDept(ctx context.Context, tenantID int64) ([]StatsByDeptRow, error) {
	rows, err := q.db.Query(ctx, statsByDept, tenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StatsByDeptRow
	for rows.Next() {
		var i StatsByDeptRow
		if err := rows.Scan(&i.Key, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

